"""Accessible HTML shells for living-brand workspaces."""

# Static HTML fragments are kept compact and visually grouped.
# ruff: noqa: E501

from uuid import UUID

HEAD = """<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/workshop.css"><script src="/assets/workshop.js" defer></script>"""
HEADER = """<a class="skip-link" href="#main-content">Skip to main content</a><header><a href="/">Brand System Maker</a><nav aria-label="Primary"><a href="/brand-systems">Living brands</a><a href="/brands">Kit library</a></nav></header>"""
DERIVATIVE_TOOLS = """<section class="derivative-tools" aria-labelledby="derivative-heading"><h3 id="derivative-heading">Create logo variants and icons</h3><p class="field-help">Choose an uploaded or generated raster logo. The source stays unchanged; every result is added as an optional managed asset.</p><label for="derivative-source">Source raster logo</label><select id="derivative-source"><option value="">Choose a raster logo</option></select><fieldset><legend>AI variants</legend><label><input type="checkbox" name="logo-variant" value="monochrome" checked> Monochrome</label><label><input type="checkbox" name="logo-variant" value="inverted" checked> Inverted</label><label><input type="checkbox" name="logo-variant" value="horizontal-lockup" checked> Horizontal lockup</label><label><input type="checkbox" name="logo-variant" value="icon-only" checked> Icon only</label></fieldset><div class="button-row"><button id="create-favicon-set" type="button">Create favicon + app icons</button><button id="create-logo-variants" type="button">Create selected AI variants</button><button id="create-vector" type="button">Vectorize to SVG</button></div><p id="derivative-status" role="status" aria-live="polite"></p></section>"""


def workspace_index() -> str:
    return f"""<!doctype html><html lang="en"><head>{HEAD}<title>Living brands</title></head><body data-page="index">{HEADER}<main id="main-content"><section class="intro"><p class="eyebrow">Local workspace</p><h1>Build a living brand system</h1><p>Create an editable system, one durable section at a time.</p><form id="workspace-form"><label for="workspace-name">Brand name</label><input id="workspace-name" required maxlength="300" placeholder="e.g. Northstar Books"><label for="brand-context">Brand context (optional)</label><textarea id="brand-context" maxlength="50000" rows="8" aria-describedby="brand-context-help" placeholder="e.g. We serve independent neighborhood bookstores fighting Amazon. Our reader is a shop owner who knows every regular by name. We sound literate and warm — never nostalgic, never corporate. The one thing only we'd say: 'A store is an argument for a kind of town.'"></textarea><p id="brand-context-help" class="field-help">The brand can only get as specific as this box. Vague in, generic out — so name the audience, the thing you're reacting against, and the one sentence only you would say. This is the raw material every generated section draws from; a paragraph of real specifics beats a page of adjectives.</p><label for="owner-name">Your name</label><input id="owner-name" required maxlength="300" placeholder="e.g. Alex Rivera"><button type="submit">Create workspace</button><p id="workspace-status" role="status" aria-live="polite"></p></form></section><section aria-labelledby="workspaces-heading"><h2 id="workspaces-heading">Your workspaces</h2><div id="workspace-list" aria-busy="true"><p>Loading…</p></div></section></main></body></html>"""


def workspace_detail(brand_id: UUID) -> str:
    return f'''<!doctype html><html lang="en"><head>{HEAD}<title>Brand workshop</title></head><body data-page="workshop" data-brand-id="{brand_id}">{HEADER}<main id="main-content"><div class="workshop-head"><p class="eyebrow">Living brand</p><h1 id="brand-title">Loading workspace…</h1><p id="revision-label"></p></div><section class="generation-panel" aria-labelledby="generation-heading"><h2 id="generation-heading">Generate a starting point</h2><p class="field-help">A blank page is the enemy of a good brand. Generate a draft to react against, then make it yours — the strongest decisions come from editing something wrong into something right, not from the first output. <strong>Complete draft</strong> fills every section; <strong>selected section</strong> fills one plus what it depends on. Pause, cancel, and hand-edit freely below.</p><div class="button-row"><button id="generate-complete" type="button">Generate complete draft</button><button id="generate-section" type="button">Generate selected section</button><button id="pause-generation" type="button" disabled>Pause generation</button><button id="cancel-generation" type="button" disabled>Cancel generation</button></div><p id="generation-status" role="status" aria-live="polite"></p><ol id="generation-progress" aria-label="Generation progress"></ol></section><div class="workshop-grid"><nav id="section-navigation" aria-label="Brand sections"></nav><section aria-labelledby="section-title"><form id="section-form"><h2 id="section-title">Select a section</h2><p class="field-help">Build the brand in passes, not in one sitting. Coherence comes from returning to earlier sections as later ones sharpen your thinking — the voice you write here should change how you write the messaging two sections down. Everything you add flows into the complete brand bible.</p><label for="section-status">Section status</label><select id="section-status" aria-describedby="status-help"><option>incomplete</option><option>draft</option><option>reviewed</option><option>approved</option></select><p id="status-help" class="field-help">Resist approving early. Brands cohere late — a section you lock now often fights a choice you make three sections from here, so let things stay <strong>draft</strong> until the whole system agrees with itself. Move <strong>incomplete → draft → reviewed → approved</strong>; only reviewed and approved count toward completion.</p><h3>Prose</h3><p class="field-help">Write the <em>why</em>, not just the <em>what</em>. A rule tells someone what to do; the reasoning behind it is what stops them relitigating a settled decision six months from now. Capture the thinking while it's fresh — future-you won't remember it.</p><div id="block-editors"></div><button id="add-paragraph" type="button">Add paragraph</button><h3>Rules</h3><p class="field-help">A rule nobody can break is just a wish. Make each one specific enough to actually fail a real piece of work, and keep them few — every rule is something the brand now has to defend forever. Set enforcement by how much it truly matters: <strong>advisory</strong>, <strong>warning</strong>, or <strong>blocking</strong>.</p><div id="rule-editors"></div><button id="add-rule" type="button">Add rule</button><h3>Tokens</h3><p class="field-help">Name colors by the job they do — <code>primary</code>, <code>accent</code>, <code>background</code> — never by how they look. Roles survive a rebrand; a token called <code>navy</code> becomes a lie the day the palette changes. Those role names also re-skin the bible live, so use a hex like <code>#1a1a1a</code>.</p><div id="token-editors"></div><button id="add-token" type="button">Add token</button><h3>Examples</h3><p class="field-help">One sharp <strong>don't</strong> teaches more than three <strong>dos</strong>. Show the plausible-but-wrong version people actually produce — the near-miss, not the obvious mistake nobody was going to make. Tag each as <strong>do</strong>, <strong>don't</strong>, or <strong>context</strong>.</p><div id="example-editors"></div><button id="add-example" type="button">Add example</button><h3>Patterns</h3><p class="field-help">Patterns are where a brand stops being taste and becomes repeatable. The test: if two people follow the same pattern and get different results, it isn't finished yet. Give each real specifications and do / don't lists (say / never-say, type scale, component specs).</p><div id="pattern-editors"></div><button id="add-pattern" type="button">Add pattern</button><button type="submit">Save section</button><p id="editor-status" role="status" aria-live="polite"></p></form></section></div><section class="asset-panel" aria-labelledby="asset-heading"><h2 id="asset-heading">Production assets</h2><p>Upload logos, fonts, or other production files. Each is stored by content hash and appears in the brand bible's asset registry.</p><ul id="asset-list" aria-label="Registered assets"></ul><form id="asset-form"><label for="asset-name">Asset name</label><input id="asset-name" required maxlength="300" placeholder="e.g. Primary logo (SVG)"><label for="asset-file">File</label><input id="asset-file" type="file" required><label class="asset-required"><input id="asset-required" type="checkbox" checked> Required for publication</label><p class="field-help">Mark an asset <strong>required</strong> only if the brand genuinely breaks without it. Required assets are promises the system keeps — it refuses to publish if one goes missing or changes underneath you. Uncheck for optional or work-in-progress files.</p><button type="submit">Upload asset</button><p id="asset-status" role="status" aria-live="polite"></p></form><form id="logo-form"><h3>Generate a logo with AI</h3><p class="field-help">Describe constraints, not vibes. "<em>One color, no text, legible at 16 pixels</em>" steers the model far better than "<em>modern and clean</em>" — the tighter the box, the more usable the mark. This draws on the brand's name, context, and color tokens.</p><label for="logo-instructions">Extra instructions (optional)</label><textarea id="logo-instructions" maxlength="2000" rows="3" placeholder="e.g. minimalist line mark, avoid text, evoke a mountain"></textarea><button type="submit">Generate logo</button><p id="logo-status" role="status" aria-live="polite"></p></form></section></main></body></html>'''


def add_derivative_tools(page: str) -> str:
    """Place derivative controls at the end of the production-assets panel."""

    marker = "</section></main></body></html>"
    return page.replace(marker, f"{DERIVATIVE_TOOLS}{marker}", 1)
